const APP_VERSION=self.ELO_APP_VERSION||'2.2.1';

// ===== v2.0 • Perfis locais, acessibilidade, tempo saudável, tutorial e backup =====
const V2_PROFILES_KEY='eloProfilesV2',V2_ACTIVE_KEY='eloActiveProfileId',V2_MIGRATION_KEY='eloProfilesV2Migrated';
const V2_AVATARS=['🌟','🦄','🌈','🎀','🐱','🦋','🎮','🎨'];
function loadProfiles(){try{const v=JSON.parse(localStorage.getItem(V2_PROFILES_KEY)||'[]');return Array.isArray(v)?v:[]}catch(_){return[]}}
function saveProfiles(v){localStorage.setItem(V2_PROFILES_KEY,JSON.stringify(v))}
function ensureProfiles(){let ps=loadProfiles();if(!ps.length){ps=[{id:'elo',name:'Elo',avatar:'🌟',ageRange:'6-8',createdAt:Date.now()}];saveProfiles(ps)}let changed=false;ps=ps.map(p=>{if(!p.ageRange){changed=true;return {...p,ageRange:'6-8'}}return p});if(changed)saveProfiles(ps);let active=localStorage.getItem(V2_ACTIVE_KEY);if(!ps.some(x=>x.id===active)){active=ps[0].id;localStorage.setItem(V2_ACTIVE_KEY,active)}if(localStorage.getItem(V2_MIGRATION_KEY)!=='1'){const oldKeys=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&(/^eloStars$|^eloFavStories$|^eloReadStories$|^eloRpgSaveV1$|^eloRpgMedals$|^eloMedal-|^eloMemoryHardWon$|^eloPuzzleWon$|^artReward|^eloDaily|^daily-/.test(k)))oldKeys.push(k)}for(const k of oldKeys){const dest=`eloProfile:${active}:${k}`;if(localStorage.getItem(dest)==null)localStorage.setItem(dest,localStorage.getItem(k))}localStorage.setItem(V2_MIGRATION_KEY,'1')}return {profiles:ps,active}}
let __profileState=ensureProfiles();
let activeProfileId=__profileState.active;
function pkey(k){return `eloProfile:${activeProfileId}:${k}`}
function pget(k){return localStorage.getItem(pkey(k))}
function pset(k,v){localStorage.setItem(pkey(k),v)}
function premove(k){localStorage.removeItem(pkey(k))}
function getActiveProfile(){return loadProfiles().find(x=>x.id===activeProfileId)||loadProfiles()[0]||{id:'elo',name:'Elo',avatar:'🌟'}}
function setActiveProfile(id){if(!loadProfiles().some(x=>x.id===id))return;localStorage.setItem(V2_ACTIVE_KEY,id);location.reload()}
function chooseAgeRange(current='6-8'){const raw=(prompt('Faixa etária do perfil:\n1 = 3–5 anos\n2 = 6–8 anos\n3 = 9–11 anos',current==='3-5'?'1':current==='9-11'?'3':'2')||'').trim();return raw==='1'?'3-5':raw==='3'?'9-11':raw==='2'?'6-8':null}
function createProfile(){requestParentAccess(createProfileUnlocked,'Digite o PIN dos responsáveis para criar um perfil.')}
function createProfileUnlocked(){const ps=loadProfiles();if(ps.length>=4)return toast('Máximo de 4 perfis neste aparelho.');let name=(prompt('Nome do perfil (somente neste aparelho):','')||'').trim().slice(0,18);if(!name)return;const ageRange=chooseAgeRange('6-8');if(!ageRange)return;const id='p'+Date.now().toString(36),avatar=V2_AVATARS[ps.length%V2_AVATARS.length];ps.push({id,name,avatar,ageRange,createdAt:Date.now()});saveProfiles(ps);localStorage.setItem(V2_ACTIVE_KEY,id);location.reload()}
function editProfileAge(id){requestParentAccess(()=>{const ps=loadProfiles(),p=ps.find(x=>x.id===id);if(!p)return;const ageRange=chooseAgeRange(p.ageRange||'6-8');if(!ageRange)return;p.ageRange=ageRange;saveProfiles(ps);if(id===activeProfileId)pset('englishAge',ageRange);renderProfileManager();renderParentV2();toast('Faixa etária atualizada 💗')},'Digite o PIN dos responsáveis para alterar a faixa etária.')}
function deleteProfile(id){requestParentAccess(()=>deleteProfileUnlocked(id),'Digite o PIN dos responsáveis para apagar um perfil.')}
function deleteProfileUnlocked(id){const ps=loadProfiles();if(ps.length<=1)return toast('Mantenha pelo menos um perfil.');const target=ps.find(x=>x.id===id);if(!target||!confirm(`Apagar o perfil ${target.name} e todo o progresso dele neste aparelho?`))return;const prefix=`eloProfile:${id}:`;const keys=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.startsWith(prefix))keys.push(k)}keys.forEach(k=>localStorage.removeItem(k));const next=ps.filter(x=>x.id!==id);saveProfiles(next);if(activeProfileId===id)localStorage.setItem(V2_ACTIVE_KEY,next[0].id);renderProfileManager();toast('Perfil removido.')}
function renderProfileManager(){const p=getActiveProfile();const ageLabel=a=>a==='3-5'?'3–5 anos':a==='9-11'?'9–11 anos':'6–8 anos';const chip=document.getElementById('profileChip');if(chip)chip.innerHTML=`<span>${p.avatar}</span><b>${escapeHtml(p.name)}</b><small>${ageLabel(p.ageRange)}</small>`;const ps=loadProfiles();const rows=ps.map(x=>`<div class="profileRow ${x.id===activeProfileId?'on':''}"><button onclick="setActiveProfile('${x.id}')"><span>${x.avatar}</span><div><b>${escapeHtml(x.name)}</b><small>${x.id===activeProfileId?'Perfil atual':'Usar este perfil'} • ${ageLabel(x.ageRange)}</small></div></button><button class="profileDelete" onclick="editProfileAge('${x.id}')" aria-label="Alterar faixa etária">🎂</button><button class="profileDelete" onclick="deleteProfile('${x.id}')" ${ps.length<=1?'disabled':''}>🗑️</button></div>`).join('');const box=document.getElementById('profileList');if(box)box.innerHTML=rows+`<button class="btn secondary full" onclick="createProfile()">＋ Criar novo perfil</button>`;const top=document.getElementById('profileListTop');if(top)top.innerHTML=rows}
function openProfileChooser(){document.getElementById('profileModal')?.classList.remove('hidden');document.body.style.overflow='hidden';renderProfileManager()}
function closeProfileChooser(){document.getElementById('profileModal')?.classList.add('hidden');document.body.style.overflow=''}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

const A11Y_KEY='eloAccessibilityV2';
function getA11y(){try{return Object.assign({large:false,contrast:false,reduce:false,big:false,speech:true},JSON.parse(localStorage.getItem(A11Y_KEY)||'{}'))}catch(_){return{large:false,contrast:false,reduce:false,big:false,speech:true}}}
function applyA11y(){const a=getA11y(),b=document.body;if(!b)return;b.classList.toggle('a11y-large',!!a.large);b.classList.toggle('a11y-contrast',!!a.contrast);b.classList.toggle('a11y-reduce',!!a.reduce);b.classList.toggle('a11y-big',!!a.big);document.querySelectorAll('[data-a11y]').forEach(el=>{const k=el.dataset.a11y;if(el.type==='checkbox')el.checked=!!a[k]});const sb=document.getElementById('speechBtn');if(sb)sb.textContent=a.speech?'🔊':'🔇'}
function setA11y(k,v){const a=getA11y();a[k]=!!v;localStorage.setItem(A11Y_KEY,JSON.stringify(a));applyA11y();toast('Preferência atualizada 💗')}
function toggleSpeech(){const a=getA11y();a.speech=!a.speech;localStorage.setItem(A11Y_KEY,JSON.stringify(a));if(!a.speech&&'speechSynthesis'in window)speechSynthesis.cancel();applyA11y();toast(a.speech?'Leitura em voz ligada 🔊':'Leitura em voz desligada 🔇')}
function speakText(txt){if(!getA11y().speech||!('speechSynthesis'in window))return toast('Leitura em voz está desligada.');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(txt||'').replace(/\s+/g,' ').trim());u.lang='pt-BR';u.rate=.95;u.pitch=1.05;speechSynthesis.speak(u)}
function readCurrentScreen(){const panel=document.querySelector('.panel.active');if(!panel)return;if(panel.id==='readerPanel')return readStoryPage();const txt=[...panel.querySelectorAll('h1,h2,h3,p,.muted,.quiz-q')].filter(x=>x.offsetParent!==null).map(x=>x.textContent.trim()).filter(Boolean).slice(0,18).join('. ');speakText(txt||'Tela atual do Dia a Dia da Elo.')}

const LIMIT_KEY='eloDailyLimitV2';
function dayKey(){const d=new Date();return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`}
function usageKey(){return `usage-${dayKey()}`}
function getTodayUsage(){return Number(pget(usageKey())||0)}
function setDailyLimit(min){localStorage.setItem(LIMIT_KEY,String(Number(min)||0));renderParentV2();toast(min?`Limite suave: ${min} minutos por dia`:'Lembrete de tempo desativado')}
function getActivityStats(){try{return JSON.parse(pget('activityStatsV1')||'{}')}catch(_){return{}}}
function trackActivity(name){const s=getActivityStats();s[name]=Number(s[name]||0)+1;pset('activityStatsV1',JSON.stringify(s))}
function getLast7Usage(){let total=0;for(let i=0;i<7;i++){const d=new Date();d.setDate(d.getDate()-i);const k=`usage-${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`;total+=Number(pget(k)||0)}return total}
function renderParentProgress(){const box=document.getElementById('parentProgressDashboard');if(!box)return;const p=getActiveProfile(),age=p.ageRange||'6-8',stats=getActivityStats(),entries=Object.entries(stats).sort((a,b)=>b[1]-a[1]);const names={games:'Jogos',rpg:'RPG',stories:'Histórias',english:'Inglês',school:'Escolinha',coloring:'Criar'};const top=entries[0]?`${names[entries[0][0]]||entries[0][0]} (${entries[0][1]}x)`:'Ainda sem dados';const oldAge=typeof englishAge!=='undefined'?englishAge:null;let eng=0;try{eng=englishOverallPercent(age)}catch(_){eng=0}box.innerHTML=`<div class="parentProgressGrid"><div><strong>${stars}</strong><span>estrelas</span></div><div><strong>${readStories.length}</strong><span>histórias</span></div><div><strong>${eng}%</strong><span>inglês ${age.replace('-', '–')}</span></div><div><strong>${getLast7Usage()} min</strong><span>últimos 7 dias</span></div></div><p class="muted" style="margin:10px 0 0">Atividade mais aberta: <b>${escapeHtml(top)}</b>. Tudo é calculado somente neste aparelho.</p>`}
function renderParentV2(){const sel=document.getElementById('dailyLimitSelect');if(sel)sel.value=localStorage.getItem(LIMIT_KEY)||'0';const u=document.getElementById('usageToday');if(u)u.textContent=`${getTodayUsage()} min`;applyA11y();renderProfileManager();renderParentProgress()}
setInterval(()=>{if(document.visibilityState!=='visible')return;const v=getTodayUsage()+1;pset(usageKey(),v);const limit=Number(localStorage.getItem(LIMIT_KEY)||0);if(limit&&v>=limit&&pget(`restWarn-${dayKey()}`)!=='1'){pset(`restWarn-${dayKey()}`,'1');document.getElementById('restOverlay')?.classList.remove('hidden')}renderParentV2()},60000);
function closeRestOverlay(){document.getElementById('restOverlay')?.classList.add('hidden')}

let tutorialSteps=[],tutorialIndex=0,tutorialKey='';
function showTutorialOnce(key,title,steps){if(pget(`tutorial-${key}`)==='1')return;tutorialKey=key;tutorialSteps=steps;tutorialIndex=0;const ov=document.getElementById('tutorialOverlay');if(!ov)return;document.getElementById('tutorialTitle').textContent=title;ov.classList.remove('hidden');document.body.style.overflow='hidden';renderTutorialStep()}
function renderTutorialStep(){const s=tutorialSteps[tutorialIndex]||'';document.getElementById('tutorialText').textContent=s;document.getElementById('tutorialCount').textContent=`${tutorialIndex+1}/${tutorialSteps.length}`;document.getElementById('tutorialNext').textContent=tutorialIndex===tutorialSteps.length-1?'Entendi!':'Próximo'}
function tutorialNext(){if(tutorialIndex<tutorialSteps.length-1){tutorialIndex++;renderTutorialStep();return}pSetTutorialDone()}
function pSetTutorialDone(){if(tutorialKey)pset(`tutorial-${tutorialKey}`,'1');document.getElementById('tutorialOverlay')?.classList.add('hidden');document.body.style.overflow='';tutorialKey=''}
function tutorialSpeak(){speakText(document.getElementById('tutorialText')?.textContent||'')}

function exportProfileBackup(){const prefix=`eloProfile:${activeProfileId}:`,data={version:2,profile:getActiveProfile(),progress:{}};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.startsWith(prefix))data.progress[k.slice(prefix.length)]=localStorage.getItem(k)}const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`dia-a-dia-da-elo-${getActiveProfile().name.replace(/[^a-z0-9_-]/gi,'_')}-backup.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup criado 💾')}
let backupImportMode='replace';
function triggerImportBackup(mode='replace'){backupImportMode=mode;document.getElementById('backupInput')?.click()}
async function importProfileBackup(input){const f=input.files?.[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!d||d.version!==2||!d.progress)throw new Error('invalid');if(backupImportMode==='new'){const ps=loadProfiles();if(ps.length>=4)return toast('Máximo de 4 perfis neste aparelho.');const id='p'+Date.now().toString(36),name=((d.profile?.name||'Perfil restaurado')+'').slice(0,18),avatar=d.profile?.avatar||V2_AVATARS[ps.length%V2_AVATARS.length],ageRange=d.profile?.ageRange||'6-8';ps.push({id,name,avatar,ageRange,createdAt:Date.now()});saveProfiles(ps);for(const [k,v] of Object.entries(d.progress))localStorage.setItem(`eloProfile:${id}:${k}`,v);localStorage.setItem(V2_ACTIVE_KEY,id);toast('Novo perfil restaurado. Reiniciando…');setTimeout(()=>location.reload(),650);return}if(!confirm('Restaurar este backup no perfil atual? O progresso atual deste perfil será apagado e substituído pelo backup.'))return;const prefix=`eloProfile:${activeProfileId}:`,keys=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.startsWith(prefix))keys.push(k)}keys.forEach(k=>localStorage.removeItem(k));for(const [k,v] of Object.entries(d.progress))pset(k,v);toast('Backup restaurado. Reiniciando…');setTimeout(()=>location.reload(),650)}catch(_){toast('Arquivo de backup inválido.')}finally{input.value='';backupImportMode='replace'}}
