function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),1900)}
let appRestoringHistory=false,appExitArmed=false;
function currentPanelId(){return document.querySelector('.panel.active')?.id||'homePanel'}
function appStateForPanel(id,nav){return {eloApp:true,type:id==='homePanel'?'home':'panel',id,nav}}
function pushAppState(state){if(appRestoringHistory)return;const cur=history.state||{};if(cur.eloApp&&cur.type===state.type&&cur.id===state.id)return;history.pushState(state,'')}
function openPanel(id,nav,fromHistory=false){const previous=currentPanelId();if(previous==='parentsPanel'&&id!=='parentsPanel')lockParentAccess();document.querySelectorAll('.panel').forEach(p=>p.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('.navbtn').forEach(b=>b.classList.toggle('active',b.dataset.nav===nav));window.scrollTo({top:0,behavior:'smooth'});if(id==='storiesPanel')renderLibrary();if(id==='parentsPanel'||id==='achievementsPanel')renderBadges();if(id==='parentsPanel')renderParentV2();if(id==='achievementsPanel'){renderV2Album();renderEnglishAlbum()}if(id==='learnPanel'){renderEnglishHomeProgress();renderSchoolChallenges();setTimeout(()=>toggleSchoolChallenges(false),0);}if(id==='englishPanel')renderEnglishSchool();if(id==='playPanel'){clearInterval(findTimer);clearTimeout(tapTimer);clearInterval(chaseInterval);trailStop()}if(id==='createPanel'){renderColoringGallery();renderPalette()}if(!fromHistory)pushAppState(appStateForPanel(id,nav))}
function appBack(){if(document.getElementById('exitConfirm')&&!document.getElementById('exitConfirm').classList.contains('hidden'))return cancelAppExit();history.back()}
function showExitConfirm(){document.getElementById('exitConfirm')?.classList.remove('hidden')}
function cancelAppExit(){document.getElementById('exitConfirm')?.classList.add('hidden')}
function confirmAppExit(){appExitArmed=true;document.getElementById('exitConfirm')?.classList.add('hidden');setTimeout(()=>history.go(-2),20);setTimeout(()=>{try{window.close()}catch(_){/* Android/PWA pode ignorar */}},350)}
function setupAppHistory(){if(history.state?.eloGuard||history.state?.eloApp)return;history.replaceState({eloGuard:true},'');history.pushState({eloApp:true,type:'home',id:'homePanel',nav:'home'},'')}
function restoreAppHistoryState(s){appRestoringHistory=true;try{document.getElementById('gameModal')?.classList.add('hidden');document.getElementById('coloringModal')?.classList.add('hidden');document.getElementById('rpgOverlay')?.classList.add('hidden');if(s?.type!=='rpg'){const rf=document.getElementById('rpgFrame');if(rf)rf.src='about:blank'}document.body.style.overflow='';clearInterval(findTimer);clearTimeout(tapTimer);clearInterval(chaseInterval);trailStop();if(!s||s.type==='home')openPanel('homePanel','home',true);else if(s.type==='panel')openPanel(s.id||'homePanel',s.nav||'home',true);else if(s.type==='game'){openPanel('playPanel','play',true);openGame(s.id,s.title,true)}else if(s.type==='coloring'){openPanel('createPanel','create',true);openColoring(Number(s.index)||0,true)}else if(s.type==='rpg'){openPanel('playPanel','play',true);openRpg(true)}}finally{appRestoringHistory=false}}
window.addEventListener('popstate',e=>{if(appExitArmed)return;if(e.state?.eloGuard){history.pushState({eloApp:true,type:'home',id:'homePanel',nav:'home'},'');restoreAppHistoryState({type:'home'});showExitConfirm();return}if(e.state?.eloApp)restoreAppHistoryState(e.state)});

let parentPendingAction=null,parentPinBuffer='',parentPinMode='verify',parentPinFirst='';
function launchExternal(url){const w=window.open(url,'_blank','noopener,noreferrer');if(!w)location.href=url}
function hasParentPin(){return /^\d{4}$/.test(localStorage.getItem('eloParentPin')||'')}
function parentUnlocked(){const until=Number(sessionStorage.getItem('eloParentUnlockedUntil')||0);if(until>Date.now())return true;sessionStorage.removeItem('eloParentUnlockedUntil');return false}
function lockParentAccess(){sessionStorage.removeItem('eloParentUnlockedUntil')}
function updatePinDots(){document.querySelectorAll('#pinDots .pinDot').forEach((d,i)=>d.classList.toggle('on',i<parentPinBuffer.length))}
function showParentPin(message,mode='verify',action=null){parentPendingAction=action;parentPinMode=mode;parentPinBuffer='';parentPinFirst='';const modal=document.getElementById('parentPinModal');document.getElementById('pinTitle').textContent=mode.startsWith('setup')?'Criar PIN dos responsáveis':'Área dos responsáveis';document.getElementById('pinMessage').textContent=message;updatePinDots();modal.classList.remove('hidden');document.body.style.overflow='hidden'}
function closeParentPin(){document.getElementById('parentPinModal').classList.add('hidden');document.body.style.overflow='';parentPinBuffer='';parentPendingAction=null;updatePinDots()}
function finishParentAccess(){sessionStorage.setItem('eloParentUnlockedUntil',String(Date.now()+5*60*1000));const cb=parentPendingAction;document.getElementById('parentPinModal').classList.add('hidden');document.body.style.overflow='';parentPendingAction=null;parentPinBuffer='';updatePinDots();if(cb)cb()}
function requestParentAccess(action,message='Digite o PIN de 4 dígitos dos responsáveis para continuar.'){if(parentUnlocked())return action();if(!hasParentPin())return showParentPin('Crie um PIN de 4 dígitos. Ele ficará salvo somente neste aparelho.','setup1',action);showParentPin(message,'verify',action)}
function pinKey(n){if(parentPinBuffer.length>=4)return;parentPinBuffer+=n;updatePinDots();if(parentPinBuffer.length===4)processParentPin()}
function pinBackspace(){parentPinBuffer=parentPinBuffer.slice(0,-1);updatePinDots()}
function processParentPin(){if(parentPinBuffer.length!==4)return;const entered=parentPinBuffer;if(parentPinMode==='setup1'){parentPinFirst=entered;parentPinBuffer='';parentPinMode='setup2';document.getElementById('pinMessage').textContent='Repita o novo PIN para confirmar.';updatePinDots();return}if(parentPinMode==='setup2'){if(entered!==parentPinFirst){parentPinBuffer='';parentPinMode='setup1';parentPinFirst='';document.getElementById('pinMessage').textContent='Os PINs não coincidiram. Crie novamente um PIN de 4 dígitos.';updatePinDots();return}localStorage.setItem('eloParentPin',entered);finishParentAccess();toast('PIN dos responsáveis criado 🔐');return}if(parentPinMode==='change1'){parentPinFirst=entered;parentPinBuffer='';parentPinMode='change2';document.getElementById('pinMessage').textContent='Repita o novo PIN para confirmar.';updatePinDots();return}if(parentPinMode==='change2'){if(entered!==parentPinFirst){parentPinBuffer='';parentPinMode='change1';parentPinFirst='';document.getElementById('pinMessage').textContent='Os PINs não coincidiram. Tente novamente.';updatePinDots();return}localStorage.setItem('eloParentPin',entered);document.getElementById('parentPinModal').classList.add('hidden');document.body.style.overflow='';parentPinBuffer='';updatePinDots();toast('PIN alterado com sucesso 🔐');return}if(entered===localStorage.getItem('eloParentPin'))finishParentAccess();else{parentPinBuffer='';document.getElementById('pinMessage').textContent='PIN incorreto. Tente novamente.';updatePinDots()}}
function changeParentPin(){parentPinBuffer='';parentPinFirst='';parentPinMode='change1';parentPendingAction=null;document.getElementById('pinTitle').textContent='Alterar PIN';document.getElementById('pinMessage').textContent='Digite um novo PIN de 4 dígitos.';updatePinDots();document.getElementById('parentPinModal').classList.remove('hidden');document.body.style.overflow='hidden'}
function openExternal(url){requestParentAccess(()=>launchExternal(url),'Digite o PIN dos responsáveis para abrir este link externo.')}
function openParents(){requestParentAccess(()=>openPanel('parentsPanel','parents'))}
function openMemberWithGate(){openExternal(MEMBER_URL)}
function openSubscribe(){openExternal(SUBSCRIBE_URL)}
function openInstagram(){openExternal(INSTAGRAM_URL)}
function openGame(id,title,fromHistory=false){if(!fromHistory)trackActivity('games');clearInterval(findTimer);clearTimeout(tapTimer);clearInterval(chaseInterval);trailStop();document.getElementById('gameModalTitle').textContent=title;document.querySelectorAll('.gameSection').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');document.getElementById('gameModal').classList.remove('hidden');document.body.style.overflow='hidden';if(!fromHistory)pushAppState({eloApp:true,type:'game',id,title});if(id==='findGame')resetFind(true);if(id==='mazeGame')startMaze();if(id==='unicornChaseGame')startChase();if(id==='memoryGame')startMemory();if(id==='puzzleGame')startPuzzle(false);if(id==='tapGameSection')startTapGame();if(id==='trailGame')startTrailGame();if(!fromHistory){const tips={findGame:['Procure a pequena estrela escondida no cenário.','Quanto maior a dificuldade, menor a estrela e menor o tempo.'],mazeGame:['Leve a Elo até o unicórnio.','Use as setas ou deslize o dedo pelo labirinto.'],unicornChaseGame:['Colete os unicórnios e fuja do fantasminha.','Planeje rotas abertas e não fique presa em cantos.'],memoryGame:['Vire duas cartas de cada vez e encontre os pares.'],puzzleGame:['Toque em duas peças para trocar de lugar.','Quando tudo estiver certo, as peças ficam bloqueadas.'],tapGameSection:['Leia o número pedido e toque nele antes do tempo acabar.'],trailGame:['Toque em Pular para desviar e coletar objetos.','Nos chefes, espere a abertura indicada por AGORA! e use Poder.']};showTutorialOnce('game-'+id,title,tips[id]||['Divirta-se e complete o desafio!'])}}
function closeGame(fromHistory=false){if(!fromHistory&&history.state?.type==='game')return history.back();clearInterval(findTimer);clearTimeout(tapTimer);clearInterval(chaseInterval);trailStop();document.getElementById('gameModal').classList.add('hidden');document.body.style.overflow=''}
function openRpg(fromHistory=false){if(!fromHistory)trackActivity('rpg');trailStop();clearInterval(findTimer);clearTimeout(tapTimer);clearInterval(chaseInterval);const frame=document.getElementById('rpgFrame');const wanted=new URL('./rpg.html?v='+encodeURIComponent(APP_VERSION)+'&profile='+encodeURIComponent(activeProfileId),location.href).href;frame.src=wanted;document.getElementById('rpgOverlay').classList.remove('hidden');document.body.style.overflow='hidden';if(!fromHistory){pushAppState({eloApp:true,type:'rpg'});showTutorialOnce('rpg','Elo e o Reino das Estrelas',['Use as setas para andar e A para falar, entrar ou interagir.','Energia mostra a vida da Elo. Magia (MP) é usada pelos Poderes.','Treine antes dos chefes, leve poções e explore lojas, casas e caminhos.','O jogo salva automaticamente e continua do ponto em que você parou.'])}}
function closeRpg(fromHistory=false){if(!fromHistory&&history.state?.type==='rpg')return history.back();const frame=document.getElementById('rpgFrame');document.getElementById('rpgOverlay').classList.add('hidden');document.body.style.overflow='';if(frame)frame.src='about:blank';renderBadges()}
window.addEventListener('message',e=>{const d=e.data||{};if(d.type==='rpg-close')closeRpg();if(d.type==='rpg-open-youtube')openExternal(CHANNEL_URL);if(d.type==='rpg-medal')renderBadges()});
function openColoring(i,fromHistory=false){if(!fromHistory)trackActivity('coloring');chooseColoring(i,true);if(!fromHistory)pushAppState({eloApp:true,type:'coloring',index:i})}
function closeColoring(fromHistory=false){if(!fromHistory&&history.state?.type==='coloring')return history.back();document.getElementById('coloringModal').classList.add('hidden');document.body.style.overflow='';if(typeof resetColorZoom==='function')resetColorZoom()}

const daily=[['Missão da Elo','Dê 5 pulinhos e faça uma pose engraçada!'],['Missão das cores','Ache 3 coisas cor-de-rosa perto de você.'],['Missão do sorriso','Faça alguém da família dar risada.'],['Missão movimento','Imite um sapinho por 10 segundos.'],['Missão desenho','Pinte um desenho da Elo e mostre para alguém.'],['Missão gentil','Faça uma gentileza para alguém da família.']];
const d=daily[new Date().getDate()%daily.length];
document.getElementById('dailyText').textContent=d[1];
const dailyKey='eloDaily'+new Date().toDateString();
if(pget(dailyKey))document.getElementById('dailyProgress').style.width='100%';
function completeDaily(){if(pget(dailyKey))return toast('A missão de hoje já foi concluída 💗');pset(dailyKey,'1');document.getElementById('dailyProgress').style.width='100%';addStars(2,'Missão concluída! +2 ⭐')}

function renderStoryStrip(){const box=document.getElementById('storyStrip');if(!box)return;box.innerHTML=STORIES.map((s,i)=>`<button class="storyCard" onclick="openStory(${i})"><div class="storyThumb" style="background-image:url('assets/stories/${s.id}-cover.webp')"><span class="numBadge">${i+1}</span><span class="heartBadge">${favorites.includes(s.id)?'♥':'♡'}</span></div><div class="storyInfo"><b>${s.title}</b><small>${s.summary}</small></div></button>`).join('')}
function renderLibrary(){const box=document.getElementById('libraryGrid');box.innerHTML=STORIES.map((s,i)=>`<article class="libCard"><div class="libCover" style="background-image:url('assets/stories/${s.id}-cover.webp')"><span class="numBadge">${i+1}</span><button class="fav ${favorites.includes(s.id)?'on':''}" onclick="toggleFav('${s.id}',event)">${favorites.includes(s.id)?'♥':'♡'}</button></div><div class="libBody"><h3>${s.title}</h3><p>${s.summary}</p><div class="libMeta"><small>📖 ${s.pages} páginas ${readStories.includes(s.id)?'• ✅ lida':''}</small><button class="btn" onclick="openStory(${i})">Ler</button></div></div></article>`).join('')}
function toggleFav(id,e){e.stopPropagation();favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];pset('eloFavStories',JSON.stringify(favorites));renderLibrary();renderStoryStrip();toast(favorites.includes(id)?'Adicionada aos favoritos 💗':'Removida dos favoritos')}
function openStory(i){trackActivity('stories');currentStory=i;currentPage=0;openPanel('readerPanel','stories');renderReader()}
function renderReader(){const s=STORIES[currentStory],page=document.getElementById('storyPage');document.getElementById('readerTitle').textContent=s.title;page.style.backgroundImage=`url('assets/stories/${s.id}.webp')`;page.style.backgroundRepeat='no-repeat';page.style.backgroundSize=`100% ${s.pages*100}%`;page.style.backgroundPosition=`center ${currentPage*(100/(s.pages-1))}%`;document.getElementById('pageCounter').textContent=`Página ${currentPage+1} de ${s.pages}`;document.getElementById('readerMoral').textContent=currentPage===s.pages-1?'✨ '+s.moral:'';document.getElementById('readerDots').innerHTML=Array.from({length:s.pages},(_,i)=>`<i class="dot ${i===currentPage?'on':''}"></i>`).join('');if(currentPage===s.pages-1&&!readStories.includes(s.id)){readStories.push(s.id);pset('eloReadStories',JSON.stringify(readStories));addStars(3,'História concluída! +3 ⭐');renderLibrary()}}
function nextPage(){const s=STORIES[currentStory];if('speechSynthesis'in window)speechSynthesis.cancel();if(currentPage<s.pages-1){currentPage++;renderReader()}else toast('Fim da história 💗')}
function prevPage(){if('speechSynthesis'in window)speechSynthesis.cancel();if(currentPage>0){currentPage--;renderReader()}else toast('Você está na primeira página')}
let touchX=0;
document.getElementById('storyPage').addEventListener('touchstart',e=>touchX=e.changedTouches[0].clientX,{passive:true});
document.getElementById('storyPage').addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-touchX;if(dx<-45)nextPage();if(dx>45)prevPage()},{passive:true});

function renderPlaylists(){document.getElementById('playlistGrid').innerHTML=PLAYLISTS.map(p=>`<button class="playlistCard" onclick="openExternal('https://youtube.com/playlist?list=${p.id}')"><div class="picon">${p.icon}</div><b>${p.title}</b><span>Abrir playlist no YouTube →</span></button>`).join('')}

