function answerKidSchool(btn){if(schoolKidLocked)return;const box=document.getElementById('quiz'),correct=box.dataset.correct;if(btn.dataset.value!==correct){btn.classList.add('bad');speakText(`Tente de novo. Toque em ${correct}`);setTimeout(()=>btn.classList.remove('bad'),600);return}schoolKidLocked=true;schoolKidScore++;btn.classList.add('good');speakText('Muito bem!');schoolKidRound++;setTimeout(()=>renderKidSchoolQuestion(false),850)}

