const ENGLISH_WORLD_ORDER=['colors','numbers','fruits','animals','greetings'];
const ENGLISH_COLOR_HEX={red:'#ef4444',blue:'#3b82f6',yellow:'#facc15',green:'#22c55e',pink:'#ff76b8',purple:'#8b5cf6',orange:'#f97316',black:'#1f2937',white:'#ffffff'};
const ENGLISH_NUMBER_VALUE={one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10};
const ENGLISH_GREETING_VISUAL={'hello':'👋🙂','goodbye':'👋🚪','please':'🙏🙂','thank-you':'🎁💗','good-morning':'☀️😊','good-night':'🌙😴','how-are-you':'🙂❓','im-fine':'😊👍'};
function englishKidVisual(item,world=englishWorldId){if(world==='colors')return `<span class="kidColorSwatch" style="background:${ENGLISH_COLOR_HEX[item.id]||'#ddd'}"></span>`;if(world==='numbers'){const n=ENGLISH_NUMBER_VALUE[item.id]||1;return `<span class="kidNumberVisual">${n}</span>`}if(world==='greetings')return `<span class="kidVisualSeq">${ENGLISH_GREETING_VISUAL[item.id]||item.emoji}</span>`;return `<span class="kidChoiceEmoji">${item.emoji}</span>`}
let englishAge=getActiveProfile().ageRange||pget('englishAge')||'6-8',englishWorldId=null,englishSession=[],englishPos=0,englishCorrect=0,englishAnswered=false,englishMode='learn';
function englishProgressKey(age=englishAge){return `englishProgressV2:${age}`}
function getEnglishProgress(age=englishAge){try{if(pget('englishProgressV2Migrated')!=='1'){const old=pget('englishProgressV1'),target=getActiveProfile().ageRange||'6-8';if(old&&!pget(englishProgressKey(target)))pset(englishProgressKey(target),old);pset('englishProgressV2Migrated','1')}const raw=pget(englishProgressKey(age));const p=JSON.parse(raw||'{}');return Object.assign({mastery:{},completed:[],certificate:false},p)}catch(_){return{mastery:{},completed:[],certificate:false}}}
function saveEnglishProgress(v,age=englishAge){pset(englishProgressKey(age),JSON.stringify(v))}
function englishMasteryKey(world,item){return `${world}:${item}`}
function englishMastery(world,item,age=englishAge){const p=getEnglishProgress(age);return Math.min(3,Number(p.mastery[englishMasteryKey(world,item)]||0))}
function englishWorldPercent(id,age=englishAge){const w=ENGLISH_WORLDS[id],p=getEnglishProgress(age);const score=w.items.reduce((n,it)=>n+Math.min(3,Number(p.mastery[englishMasteryKey(id,it.id)]||0)),0);return Math.round(score/(w.items.length*3)*100)}
function englishOverallPercent(age=englishAge){return Math.round(ENGLISH_WORLD_ORDER.reduce((n,id)=>n+englishWorldPercent(id,age),0)/ENGLISH_WORLD_ORDER.length)}
function setEnglishAge(age){if(!ENGLISH_AGES[age])return;englishAge=age;pset('englishAge',age);const ps=loadProfiles(),p=ps.find(x=>x.id===activeProfileId);if(p){p.ageRange=age;saveProfiles(ps)}renderEnglishSchool();renderProfileManager();toast(`Atividades para ${ENGLISH_AGES[age].label} 💗`)}
function speakEnglish(txt,slow=false){if(!('speechSynthesis'in window))return toast('Este aparelho não oferece leitura em voz.');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(txt);u.lang='en-US';u.rate=slow?.68:.78;u.pitch=1.04;speechSynthesis.speak(u)}
function speakEnglishItem(world,id){const it=ENGLISH_WORLDS[world]?.items.find(x=>x.id===id);if(it)speakEnglish(it.en)}
function repeatEnglishQuestion(){const q=englishSession[englishPos];if(q)speakEnglish(q.item.en,true)}
function openEnglishSchool(){trackActivity('english');openPanel('englishPanel','learn');englishWorldId=null;englishMode='home';renderEnglishSchool();showTutorialOnce('english-v220','Inglês da Elo 🇺🇸',['Escolha a faixa etária para adaptar as atividades.','De 3 a 5 anos, a criança ouve e toca nas figuras, cores e quantidades, sem precisar ler.','Para ouvir uma palavra novamente, basta tocar na própria cor, número, fruta, animal ou figura.','Nas faixas maiores entram leitura, escrita e frases.'])}
function renderEnglishHomeProgress(){const bar=document.getElementById('englishHomeProgress'),txt=document.getElementById('englishHomeProgressText'),pct=englishOverallPercent();if(bar)bar.style.width=pct+'%';if(txt)txt.textContent=pct+'%'}
function renderEnglishSchool(){renderEnglishHomeProgress();const root=document.getElementById('englishRoot');if(!root)return;if(englishWorldId&&englishMode!=='home')return renderEnglishWorld();const p=getEnglishProgress(),overall=englishOverallPercent(),kid=englishAge==='3-5';root.innerHTML=`<div class="englishHero"><h3>Aprenda inglês brincando 🌈</h3><p>${kid?'Para os pequenos: ouvir, ver e tocar. Sem precisar ler nas atividades.':'5 mundos iniciais com áudio, imagens, escrita e revisão.'} O progresso pertence ao perfil ${escapeHtml(getActiveProfile().name)}.</p><div class="ageGrid">${Object.entries(ENGLISH_AGES).map(([id,a])=>`<button class="ageBtn ${englishAge===id?'on':''}" onclick="setEnglishAge('${id}')">${a.label}<small>${a.desc}</small></button>`).join('')}</div><div class="engProgressWrap"><div class="engProgressTrack"><i style="width:${overall}%"></i></div><b>${overall}% dominado</b></div></div><div class="card"><h3>Escolha um mundo</h3><p class="muted">Cada palavra avança de Aprendendo → Praticando → Dominei.</p><div class="engWorldGrid">${ENGLISH_WORLD_ORDER.map(id=>{const w=ENGLISH_WORLDS[id],pct=englishWorldPercent(id),done=p.completed.includes(id);return `<button class="engWorld ${done?'done':''}" onclick="openEnglishWorld('${id}')"><span class="ewPct">${done?'🏅 ':''}${pct}%</span><span class="ewIcon">${w.icon}</span><b>${w.name}</b><small>${w.items.length} palavras e expressões</small><div class="miniProgress"><i style="width:${pct}%"></i></div></button>`}).join('')}</div></div><div class="card"><h3>Suas medalhas 🇺🇸</h3><div class="engMedalGrid">${renderEnglishMedalsHtml()}</div>${renderEnglishCertificateHtml()}</div>`}
function openEnglishWorld(id){if(!ENGLISH_WORLDS[id])return;englishWorldId=id;englishMode='learn';renderEnglishWorld()}
function closeEnglishWorld(){englishWorldId=null;englishMode='home';renderEnglishSchool()}
function masteryDots(n){return `${'●'.repeat(n)}${'○'.repeat(3-n)}`}
function masteryLabel(n){return n>=3?'Dominei':n===2?'Praticando':n===1?'Aprendendo':'Novo'}
function renderEnglishWorld(){const root=document.getElementById('englishRoot'),w=ENGLISH_WORLDS[englishWorldId];if(!root||!w)return;if(englishMode==='practice')return renderEnglishActivity();const kid=englishAge==='3-5';root.innerHTML=`<div class="card"><button class="smallBtn" onclick="closeEnglishWorld()">‹ Mundos</button><div class="engWorldHead" style="margin-top:12px"><div class="bigIcon">${w.icon}</div><div><h3>${w.name}</h3><p class="muted" style="margin:3px 0">${kid?'Toque nas figuras para ouvir.':'Toque em qualquer cartão para ouvir e repita em voz alta!'}</p></div></div><div class="engWordGrid">${w.items.map(it=>{const m=englishMastery(englishWorldId,it.id);if(kid)return `<button class="engWord kid" onclick="speakEnglishItem('${englishWorldId}','${it.id}')" aria-label="Ouvir ${escapeHtml(it.en)}">${englishKidVisual(it,englishWorldId)}</button>`;return `<button class="engWord" onclick="speakEnglishItem('${englishWorldId}','${it.id}')" aria-label="Ouvir ${escapeHtml(it.en)}"><span class="emoji">${it.emoji}</span><b>${escapeHtml(it.en)}</b><small>${escapeHtml(it.pt)}</small><div class="masteryDots">${masteryDots(m)} • ${masteryLabel(m)}</div></button>`}).join('')}</div><div class="engActions"><button class="btn" onclick="startEnglishPractice('${englishWorldId}',false)">🎮 ${kid?'▶️':'Praticar'}</button><button class="btn secondary" onclick="startEnglishPractice('${englishWorldId}',true)">🧠 ${kid?'⭐':'Revisão inteligente'}</button></div></div>`}
function englishWeakItems(id){const w=ENGLISH_WORLDS[id];return [...w.items].sort((a,b)=>englishMastery(id,a.id)-englishMastery(id,b.id)||Math.random()-.5)}
function startEnglishPractice(id,review=false){englishWorldId=id;englishMode='practice';englishCorrect=0;englishPos=0;englishAnswered=false;const w=ENGLISH_WORLDS[id],age=ENGLISH_AGES[englishAge];let items=review?englishWeakItems(id):shuffle(w.items);items=items.slice(0,Math.min(8,items.length));englishSession=items.map((it,i)=>({item:it,type:age.types[i%age.types.length]}));englishSession=shuffle(englishSession);renderEnglishActivity()}
function englishOptions(item,count=4){const w=ENGLISH_WORLDS[englishWorldId],others=shuffle(w.items.filter(x=>x.id!==item.id)).slice(0,Math.max(1,count-1));return shuffle([item,...others])}
function scrambleEnglish(s){const chars=s.replace(/[^a-zA-Z]/g,'').toUpperCase().split('');let out=shuffle(chars);if(out.join('')===chars.join('')&&out.length>2)out=[...out.slice(1),out[0]];return out.join(' ')}
function normalizeEnglish(s){return String(s||'').toLowerCase().trim().replace(/[’']/g,"'").replace(/[?.!,]/g,'').replace(/\s+/g,' ')}
function renderEnglishActivity(){const root=document.getElementById('englishRoot'),w=ENGLISH_WORLDS[englishWorldId];if(!root)return;if(englishPos>=englishSession.length)return finishEnglishPractice();const q=englishSession[englishPos],it=q.item;englishAnswered=false;let body='';if(englishAge==='3-5'){const opts=englishOptions(it,3);body=`<div class="kidListenHint"><button onclick="repeatEnglishQuestion()" aria-label="Ouvir novamente">👂</button></div><div class="engKidChoices">${opts.map(o=>`<button class="kidChoice" data-answer="${o.id}" onclick="answerEnglishChoice('${o.id}')" aria-label="Opção">${englishKidVisual(o,englishWorldId)}</button>`).join('')}</div>`;setTimeout(()=>repeatEnglishQuestion(),350)}else if(q.type==='listen'){body=`<div class="engPrompt"><span class="bigEmoji">🎧</span><h3>Ouça e escolha</h3><button class="engAudioBtn" onclick="repeatEnglishQuestion()">🔊 Ouvir novamente</button><p>Qual imagem combina com o que você ouviu?</p></div><div class="engChoices">${englishOptions(it).map(o=>`<button class="engChoice" data-answer="${o.id}" onclick="answerEnglishChoice('${o.id}')"><span class="choiceEmoji">${o.emoji}</span>${escapeHtml(o.en)}</button>`).join('')}</div>`;setTimeout(()=>speakEnglish(it.en,true),300)}else if(q.type==='choose'){body=`<div class="engPrompt"><button class="bigEmoji" style="border:0;background:transparent" onclick="repeatEnglishQuestion()">${it.emoji}</button><h3>Como se diz “${escapeHtml(it.pt)}” em inglês?</h3></div><div class="engChoices">${englishOptions(it).map(o=>`<button class="engChoice" data-answer="${o.id}" onclick="answerEnglishChoice('${o.id}')">${escapeHtml(o.en)}</button>`).join('')}</div>`}else if(q.type==='scramble'){body=`<div class="engPrompt"><button class="bigEmoji" style="border:0;background:transparent" onclick="repeatEnglishQuestion()">${it.emoji}</button><h3>Organize e escreva a palavra</h3><p>${escapeHtml(it.pt)}</p></div><div class="engScramble">${scrambleEnglish(it.en)}</div>${englishWriteBox()}`}else if(q.type==='sentence'){body=`<div class="engPrompt"><button class="bigEmoji" style="border:0;background:transparent" onclick="repeatEnglishQuestion()">${it.emoji}</button><h3>Complete a frase</h3><p style="font-size:18px;font-weight:800;color:var(--ink)">${escapeHtml(it.sentence)}</p></div>${englishWriteBox()}`}else if(q.type==='translate'){body=`<div class="engPrompt"><button class="bigEmoji" style="border:0;background:transparent" onclick="repeatEnglishQuestion()">${it.emoji}</button><h3>Escreva em inglês</h3><p style="font-size:18px">${escapeHtml(it.pt)}</p></div>${englishWriteBox()}`}else{body=`<div class="engPrompt"><button class="bigEmoji" style="border:0;background:transparent" onclick="repeatEnglishQuestion()">${it.emoji}</button><h3>Escreva em inglês</h3><p>${escapeHtml(it.pt)}</p></div>${englishWriteBox()}`};root.innerHTML=`<div class="card engActivity ${englishAge==='3-5'?'engKidMode':''}"><div class="engActivityTop"><button class="smallBtn" onclick="englishMode='learn';renderEnglishWorld()">✕ Sair</button><span class="engPill">${englishPos+1}/${englishSession.length}${englishAge==='3-5'?'':' • '+englishCorrect+' acertos'}</span></div>${body}<div id="engFeedback"></div></div>`;if(['write','scramble','sentence','translate'].includes(q.type)&&englishAge!=='3-5')setTimeout(()=>document.getElementById('englishAnswer')?.focus(),100)}
function englishWriteBox(){return `<div class="engWrite"><input id="englishAnswer" type="text" inputmode="text" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Escreva em inglês" onkeydown="if(event.key==='Enter')checkEnglishWrite()"><button class="btn" onclick="checkEnglishWrite()">OK</button></div>`}
function updateEnglishMastery(correct){const q=englishSession[englishPos],p=getEnglishProgress(),k=englishMasteryKey(englishWorldId,q.item.id);if(correct)p.mastery[k]=Math.min(3,Number(p.mastery[k]||0)+1);saveEnglishProgress(p)}
function answerEnglishChoice(id){if(englishAnswered)return;const q=englishSession[englishPos],ok=id===q.item.id;if(englishAge==='3-5'){const picked=document.querySelector(`.kidChoice[data-answer="${id}"]`);if(!ok){picked?.classList.add('bad');speakEnglish(q.item.en,true);setTimeout(()=>picked?.classList.remove('bad'),650);return}englishAnswered=true;document.querySelectorAll('.kidChoice').forEach(b=>{b.disabled=true;if(b.dataset.answer===q.item.id)b.classList.add('good')});finishEnglishQuestion(true);return}englishAnswered=true;document.querySelectorAll('.engChoice').forEach(b=>{b.disabled=true;if(b.dataset.answer===q.item.id)b.classList.add('good');else if(b.dataset.answer===id&&!ok)b.classList.add('bad')});finishEnglishQuestion(ok)}
function checkEnglishWrite(){if(englishAnswered)return;const q=englishSession[englishPos],input=document.getElementById('englishAnswer');if(!input||!input.value.trim())return toast('Escreva uma resposta 😊');englishAnswered=true;input.disabled=true;const ok=normalizeEnglish(input.value)===normalizeEnglish(q.item.en);finishEnglishQuestion(ok)}
function finishEnglishQuestion(ok){const q=englishSession[englishPos];if(ok){englishCorrect++;updateEnglishMastery(true);speakEnglish(q.item.en);if(englishAge==='3-5'){const f=document.getElementById('engFeedback');if(f)f.innerHTML='<div class="kidFeedback">⭐✅</div>';renderEnglishHomeProgress();setTimeout(()=>{if(englishAnswered)nextEnglishQuestion()},950);return}showEnglishFeedback(true,`Great! ${q.item.en} ⭐`);renderEnglishHomeProgress();setTimeout(()=>{if(englishAnswered)nextEnglishQuestion()},900);return}else{updateEnglishMastery(false);speakEnglish(q.item.en,true);showEnglishFeedback(false,`Quase! A resposta é “${q.item.en}”.`)}renderEnglishHomeProgress()}
function showEnglishFeedback(ok,msg){const f=document.getElementById('engFeedback');if(!f)return;f.innerHTML=`<div class="engFeedback ${ok?'ok':'no'}">${escapeHtml(msg)}</div>${ok?'<div class="engAutoNext">Próxima automaticamente…</div>':`<button class="btn engNext" onclick="nextEnglishQuestion()">${englishPos===englishSession.length-1?'Ver resultado':'Próxima →'}</button>`}`}
function nextEnglishQuestion(){englishPos++;englishAnswered=false;renderEnglishActivity()}
function finishEnglishPractice(){const root=document.getElementById('englishRoot'),p=getEnglishProgress(),passed=englishCorrect>=Math.ceil(englishSession.length*.7),first=!p.completed.includes(englishWorldId);if(passed&&!p.completed.includes(englishWorldId))p.completed.push(englishWorldId);if(passed&&first){addStars(3,`${ENGLISH_WORLDS[englishWorldId].medal}! +3 ⭐`)}if(p.completed.length>=ENGLISH_WORLD_ORDER.length&&!p.certificate){p.certificate=true;addStars(5,`Inglês ${ENGLISH_AGES[englishAge].label} concluído! +5 ⭐`)}saveEnglishProgress(p);renderBadges();renderV2Album();if(englishAge==='3-5'){root.innerHTML=`<div class="card engEnd"><div style="font-size:72px">${passed?'🏅⭐':'💗🌈'}</div><div class="score">${englishCorrect}/${englishSession.length}</div><div class="engActions"><button class="btn" style="font-size:30px" onclick="startEnglishPractice('${englishWorldId}',true)" aria-label="Jogar novamente">🔁</button><button class="btn secondary" style="font-size:30px" onclick="closeEnglishWorld()" aria-label="Voltar aos mundos">🏠</button></div></div>`;if(typeof speakText==='function')setTimeout(()=>speakText(passed?'Muito bem! Você terminou a atividade.':'Muito bem por tentar! Vamos brincar mais uma vez.'),150);renderEnglishHomeProgress();return}root.innerHTML=`<div class="card engEnd"><span style="font-size:52px">${passed?'🏅':'💗'}</span><div class="score">${englishCorrect}/${englishSession.length}</div><h3>${passed?'Muito bem!':'Vamos praticar mais um pouco!'}</h3><p class="muted">${passed?`Você concluiu ${ENGLISH_WORLDS[englishWorldId].name}. Continue praticando para dominar todas as palavras.`:'Use a Revisão Inteligente para treinar as palavras que ainda estão difíceis.'}</p><div class="engActions"><button class="btn" onclick="startEnglishPractice('${englishWorldId}',true)">🧠 Revisar</button><button class="btn secondary" onclick="englishMode='learn';renderEnglishWorld()">📖 Palavras</button></div><button class="smallBtn" style="margin-top:12px" onclick="closeEnglishWorld()">← Voltar aos mundos</button></div>`;renderEnglishHomeProgress()}
function renderEnglishMedalsHtml(age=englishAge){const p=getEnglishProgress(age);return ENGLISH_WORLD_ORDER.map(id=>{const w=ENGLISH_WORLDS[id],on=p.completed.includes(id);return `<div class="engMedal ${on?'on':''}"><span>${on?w.icon:'🔒'}</span><b>${w.name}</b></div>`}).join('')}
function renderEnglishCertificateHtml(age=englishAge){const p=getEnglishProgress(age),label=ENGLISH_AGES[age]?.label||age;return p.certificate?`<div class="engCertificate"><span style="font-size:32px">🏆</span><strong>Inglês da Elo — ${label}</strong><small>${escapeHtml(getActiveProfile().name)} completou Cores, Números, Frutas, Animais e Saudações nesta faixa.</small></div>`:''}
function renderEnglishAlbum(){const m=document.getElementById('englishAlbumMedals'),c=document.getElementById('englishAlbumCertificate');if(m)m.innerHTML=Object.keys(ENGLISH_AGES).map(age=>`<div class="engAgeCollection"><h4>${ENGLISH_AGES[age].label}</h4><div class="engMedalGrid">${renderEnglishMedalsHtml(age)}</div>${renderEnglishCertificateHtml(age)}</div>`).join('');if(c)c.innerHTML='';renderEnglishHomeProgress()}
function englishAchievementCount(){return Object.keys(ENGLISH_AGES).reduce((sum,age)=>{const p=getEnglishProgress(age);return sum+p.completed.length+(p.certificate?1:0)},0)}
// ===== fim v2.1.1 Inglês =====

const ACH=[
 {icon:'⭐',name:'Primeira estrela',ok:()=>stars>=1},
 {icon:'🌈',name:'Exploradora',ok:()=>stars>=10},
 {icon:'👑',name:'Super Elo',ok:()=>stars>=25},
 {icon:'📚',name:'Leitora de Aventuras',ok:()=>readStories.length>=1},
 {icon:'🏆',name:'Mestre das Aventuras',ok:()=>readStories.length>=4},
 {icon:'🎨',name:'Artista do dia',ok:()=>!!pget('artReward'+new Date().toDateString())},
 {icon:'🧠',name:'Craque da Escolinha',ok:()=>stars>=40},
 {icon:'💗',name:'Missão do dia',ok:()=>!!pget(dailyKey)}
];
function renderBadges(){const baseUnlocked=ACH.filter(x=>x.ok()).length,medalUnlocked=MEDAL_GAMES.reduce((n,g)=>n+['easy','medium','hard'].filter(level=>hasGameMedal(g.id,level)).length,0),rpgUnlocked=getRpgMedals().length,englishUnlocked=englishAchievementCount(),unlocked=baseUnlocked+medalUnlocked+rpgUnlocked+englishUnlocked,total=ACH.length+MEDAL_GAMES.length*3+RPG_MEDALS.length+18;const html=ACH.map(x=>`<div class="badge ${x.ok()?'on':''}"><span>${x.icon}</span><strong>${x.name}</strong><small>${x.ok()?'Conquistada!':'Continue brincando'}</small></div>`).join('');const all=document.getElementById('allBadges');if(all)all.innerHTML=html;renderGameMedals();renderRpgMedals();renderEnglishAlbum();const home=document.getElementById('achievementCountHome');if(home)home.textContent=unlocked;const u=document.getElementById('achievementUnlocked');if(u)u.textContent=unlocked;const t=document.getElementById('achievementTotal');if(t)t.textContent=total}
function renderV2Album(){const p=getActiveProfile(),name=document.getElementById('albumProfileName'),avatar=document.getElementById('albumAvatar');if(name)name.textContent=p.name;if(avatar)avatar.textContent=p.avatar;const st=document.getElementById('albumStars');if(st)st.textContent=stars;const sr=document.getElementById('albumStories');if(sr)sr.textContent=readStories.length;let lvl=1;try{const s=JSON.parse(pget('eloRpgSaveV1')||'null');if(s?.level)lvl=s.level}catch(_){}const rl=document.getElementById('albumRpgLevel');if(rl)rl.textContent=lvl;const gm=MEDAL_GAMES.reduce((n,g)=>n+['easy','medium','hard'].filter(l=>hasGameMedal(g.id,l)).length,0)+getRpgMedals().length+englishAchievementCount();const am=document.getElementById('albumMedals');if(am)am.textContent=gm;renderEnglishAlbum()}


