if('serviceWorker' in navigator){
  navigator.serviceWorker.addEventListener('controllerchange',()=>{
    if(!sessionStorage.getItem('elo-reloaded-'+APP_VERSION)){
      sessionStorage.setItem('elo-reloaded-'+APP_VERSION,'1');
      location.reload();
    }
  });
  navigator.serviceWorker.register('./sw.js?v='+encodeURIComponent(APP_VERSION),{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{});
}

